-- Everyday search words for the new subspecialties (added only if not already there).
insert into condition_keywords (term_en, term_ar, specialty_id, subspecialty_id)
select k.term_en, k.term_ar, s.id, x.id
from (values
  ('obgyn', 'fetal-medicine', 'fetal scan', 'سونار الجنين'),
  ('obgyn', 'fetal-medicine', '4D ultrasound', 'سونار رباعي الأبعاد'),
  ('obgyn', 'fetal-medicine', 'fetal echo', 'إيكو الجنين'),
  ('obgyn', 'ivf', 'IVF', 'أطفال الأنابيب'),
  ('obgyn', 'ivf', 'ICSI', 'حقن مجهري'),
  ('obgyn', 'pcos', 'polycystic ovary', 'تكيس المبايض'),
  ('ophthalmology', 'cataract', 'cataract', 'مياه بيضاء'),
  ('ophthalmology', 'glaucoma', 'glaucoma', 'مياه زرقاء'),
  ('ophthalmology', 'strabismus', 'squint', 'حول'),
  ('internal-medicine', 'nephrology', 'kidney failure', 'فشل كلوي'),
  ('internal-medicine', 'endocrinology', 'thyroid', 'الغدة الدرقية'),
  ('internal-medicine', 'rheumatology', 'rheumatoid arthritis', 'روماتويد'),
  ('internal-medicine', 'hematology', 'anemia', 'أنيميا'),
  ('internal-medicine', 'pulmonology', 'chest infection', 'التهاب رئوي'),
  ('internal-medicine', 'obesity-nutrition', 'obesity', 'سمنة'),
  ('orthopedics', 'osteoporosis', 'osteoporosis', 'هشاشة العظام'),
  ('orthopedics', 'trauma', 'fracture', 'كسر'),
  ('dermatology', 'psoriasis-vitiligo', 'psoriasis', 'صدفية'),
  ('dermatology', 'psoriasis-vitiligo', 'vitiligo', 'بهاق'),
  ('ent', 'snoring-sleep-apnea', 'snoring', 'شخير'),
  ('ent', 'vertigo', 'dizziness', 'دوخة'),
  ('neurology', 'dementia', 'memory loss', 'ضعف الذاكرة'),
  ('neurology', 'movement-disorders', 'parkinson', 'باركنسون'),
  ('psychiatry', 'addiction', 'addiction', 'إدمان'),
  ('psychiatry', 'anxiety-depression', 'depression', 'اكتئاب'),
  ('urology', 'prostate', 'prostate', 'بروستاتا'),
  ('urology', 'male-infertility', 'male infertility', 'تأخر الإنجاب عند الرجال'),
  ('dentistry', 'periodontics', 'bleeding gums', 'نزيف اللثة'),
  ('dentistry', 'prosthodontics', 'dentures', 'طقم أسنان'),
  ('pediatrics', 'vaccination', 'vaccination', 'تطعيمات'),
  ('cardiology', 'hypertension', 'hypertension', 'ارتفاع ضغط الدم')
) as k(spec, sub, term_en, term_ar)
join specialties s on s.slug = k.spec
join subspecialties x on x.specialty_id = s.id and x.slug = k.sub
where not exists (select 1 from condition_keywords c where lower(c.term_en) = lower(k.term_en) or c.term_ar = k.term_ar);
